import json, numpy as np

# Deep dive: for each problem, show which phases have None and their segment counts
# across all sparsity levels
all_missing = {}
for sp in ['s015','s020','s025','s030']:
    path = f'/root/autodl-tmp/pacs/profiling_output_v6_importance_{sp}/profiling_results.json'
    with open(path) as f:
        data = json.load(f)
    ppi = data['per_problem_ii']
    for level_str, items in ppi.items():
        key = f'{sp}_{level_str}'
        for p in items:
            pid = p['problem_id']
            if pid not in all_missing:
                all_missing[pid] = {}
            all_missing[pid][key] = {
                'h': (p.get('ii_high') is not None, p['n_segments_high']),
                'm': (p.get('ii_mid') is not None, p['n_segments_mid']),
                'l': (p.get('ii_low') is not None, p['n_segments_low']),
            }

# Show problems that are missing low in ANY sparsity level
print('=== Problems missing low phase (any level) ===')
print(f'{\"problem_id\":<45} s015 s020 s025 s030')
for pid in sorted(all_missing.keys()):
    info = all_missing[pid]
    any_missing = False
    row = f'{pid:<45}'
    for sp in ['s015','s020','s025','s030']:
        level_key = [k for k in info if k.startswith(sp)]
        if level_key:
            lk = level_key[0]
            has_l, n_l = info[lk]['l']
            has_h, n_h = info[lk]['h']
            if not has_l:
                any_missing = True
                row += f' L:x({n_l:2d})'
            else:
                row += f' L:o({n_l:2d})'
        else:
            row += '  N/A    '
    if any_missing:
        print(row)
"
